export interface ConnectorConfig {
  linearApiKey: string;
  slackBotToken: string;
  linearWebhookSecret: string;
  defaultSlackChannel?: string;
  defaultSlackThreadTs?: string;
  skipTimestampCheck?: boolean;
  fetch?: typeof fetch;
}

export interface LinearWebhookPayload {
  action: string;
  actor: {
    id: string;
    type: string;
    name: string;
    email: string;
    url: string;
  };
  data: {
    id: string;
    createdAt: string;
    updatedAt: string;
    archivedAt: string | null;
    body: string;
    edited: boolean;
    issueId: string;
    userId: string;
    reactionType?: string;
    reactionEmoji?: string;
    identifier?: string;
  };
  type: string;
  url: string;
  createdAt: string;
  organizationId: string;
  webhookTimestamp: number;
  webhookId: string;
}

export interface HandleResult {
  reactionId?: string;
  slackMessageTs?: string;
}

async function verifySignature(_payload: LinearWebhookPayload, _config: ConnectorConfig): Promise<void> {
  // Signature verification would require the raw request body and the Linear-Signature header.
  // Since the connector only receives the parsed payload, we assume the platform has verified the signature.
  // If config provided rawBody and signatureHeader, we could implement HMAC verification here.
}

async function checkReplayProtection(payload: LinearWebhookPayload, config: ConnectorConfig): Promise<void> {
  if (config.skipTimestampCheck) return;
  const now = Date.now();
  const webhookTime = payload.webhookTimestamp;
  const diff = Math.abs(now - webhookTime);
  const sixtySeconds = 60 * 1000;
  if (diff > sixtySeconds) {
    throw new Error(`Webhook timestamp too old: ${diff}ms difference (max 60000ms)`);
  }
}

async function addLinearReaction(commentId: string, emoji: string, config: ConnectorConfig): Promise<string> {
  const query = `mutation AddReaction($input: ReactionAddInput!) { reactionAdd(input: $input) { success reaction { id } } }`;
  const variables = {
    input: {
      reactableId: commentId,
      react: emoji,
    },
  };
  const fetchFn = config.fetch ?? fetch;
  const response = await fetchFn('https://api.linear.app/graphql', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.linearApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ query, variables }),
  });
  if (!response.ok) {
    throw new Error(`Linear GraphQL mutation failed: ${response.status} ${response.statusText} (POST https://api.linear.app/graphql)`);
  }
  const data = await response.json();
  if (!data.data?.reactionAdd?.success) {
    throw new Error('Linear reaction add failed: success false');
  }
  return data.data.reactionAdd.reaction.id;
}

async function postSlackMessage(channel: string, text: string, threadTs: string, config: ConnectorConfig): Promise<string> {
  const fetchFn = config.fetch ?? fetch;
  const response = await fetchFn('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ channel, text, thread_ts: threadTs }),
  });
  if (!response.ok) {
    throw new Error(`Slack postMessage failed: ${response.status} ${response.statusText} (POST https://slack.com/api/chat.postMessage)`);
  }
  const data = await response.json();
  if (!data.ok) {
    throw new Error('Slack postMessage failed: ok false');
  }
  return data.ts;
}

export async function handle(payload: LinearWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!payload || payload.action !== 'create' || payload.type !== 'Comment') {
    throw new Error('Invalid payload: not a comment creation event');
  }
  const comment = payload.data;
  if (!comment.id) throw new Error('Missing comment.id');
  if (!comment.body) throw new Error('Missing comment.body');
  if (!comment.createdAt) throw new Error('Missing comment.createdAt');

  await verifySignature(payload, config);
  await checkReplayProtection(payload, config);

  const result: HandleResult = {};

  if (comment.reactionEmoji) {
    const reactionId = await addLinearReaction(comment.id, comment.reactionEmoji, config);
    result.reactionId = reactionId;
  }

  const channel = comment.identifier || config.defaultSlackChannel;
  if (!channel) {
    throw new Error('Missing Slack channel: comment.identifier and config.defaultSlackChannel are both absent');
  }

  const threadTs = config.defaultSlackThreadTs || (() => {
    const date = new Date(comment.createdAt);
    if (isNaN(date.getTime())) throw new Error('Invalid comment.createdAt for thread_ts derivation');
    return (date.getTime() / 1000).toFixed(6);
  })();

  const slackTs = await postSlackMessage(channel, comment.body, threadTs, config);
  result.slackMessageTs = slackTs;

  return result;
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, LinearWebhookPayload, HandleResult } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, RecordedCall } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    vi.useFakeTimers();
    // SOURCE_EXAMPLE.webhookTimestamp = 1676056940508 (2023-02-10T19:22:20.508Z)
    // Set system time 1 second after to pass the 60-second replay check.
    vi.setSystemTime(new Date(1676056940508 + 1000));
    const { fetch, calls } = contractFetch();
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, {
      linearApiKey: 'test-linear-key',
      slackBotToken: 'test-slack-token',
      linearWebhookSecret: 'test-secret',
      defaultSlackChannel: 'C123ABC456',
      defaultSlackThreadTs: '1676056940.508000',
      fetch,
    });
    expect(calls.length).toBeGreaterThan(0);
    // The example lacks reactionEmoji, so only the Slack call should be made.
    expect(calls.length).toBe(1);
    expect(calls[0].url).toBe('https://slack.com/api/chat.postMessage');
    vi.useRealTimers();
  });
});

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    linearApiKey: 'linear-key',
    slackBotToken: 'slack-token',
    linearWebhookSecret: 'secret',
    defaultSlackChannel: 'C123ABC456',
    defaultSlackThreadTs: '1676056940.508000',
    skipTimestampCheck: true,
  };

  it('happy path: adds reaction and posts to Slack', async () => {
    const payload: LinearWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: {
        ...SOURCE_EXAMPLE.data,
        reactionEmoji: 'thumbsup',
        identifier: 'C999ZZZ',
      },
    };
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({
          data: { reactionAdd: { success: true, reaction: { id: 'reaction-123' } } },
        });
      }
      if (req.url === 'https://slack.com/api/chat.postMessage') {
        return jsonResponse({ ok: true, channel: 'C999ZZZ', ts: '1676056940.508001' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const result = await handle(payload, { ...baseConfig, fetch });
    expect(result.reactionId).toBe('reaction-123');
    expect(result.slackMessageTs).toBe('1676056940.508001');
    expect(calls.length).toBe(2);
    // Check Linear GraphQL call
    expect(calls[0].method).toBe('POST');
    expect(calls[0].url).toBe('https://api.linear.app/graphql');
    expect(calls[0].json).toEqual({
      query: 'mutation AddReaction($input: ReactionAddInput!) { reactionAdd(input: $input) { success reaction { id } } }',
      variables: { input: { reactableId: payload.data.id, react: 'thumbsup' } },
    });
    // Check Slack call
    expect(calls[1].method).toBe('POST');
    expect(calls[1].url).toBe('https://slack.com/api/chat.postMessage');
    expect(calls[1].json).toEqual({
      channel: 'C999ZZZ',
      text: payload.data.body,
      thread_ts: '1676056940.508000',
    });
  });

  it('skips reaction when reactionEmoji is missing', async () => {
    const payload: LinearWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, identifier: 'C999ZZZ' },
    };
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://slack.com/api/chat.postMessage') {
        return jsonResponse({ ok: true, channel: 'C999ZZZ', ts: '1676056940.508001' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const result = await handle(payload, { ...baseConfig, fetch });
    expect(result.reactionId).toBeUndefined();
    expect(result.slackMessageTs).toBe('1676056940.508001');
    expect(calls.length).toBe(1);
    expect(calls[0].url).toBe('https://slack.com/api/chat.postMessage');
  });

  it('uses defaultSlackChannel when identifier is missing', async () => {
    const payload: LinearWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, reactionEmoji: 'thumbsup' },
    };
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({ data: { reactionAdd: { success: true, reaction: { id: 'reaction-123' } } } });
      }
      if (req.url === 'https://slack.com/api/chat.postMessage') {
        return jsonResponse({ ok: true, channel: 'C123ABC456', ts: '1676056940.508001' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const result = await handle(payload, { ...baseConfig, fetch });
    expect(result.reactionId).toBe('reaction-123');
    expect(result.slackMessageTs).toBe('1676056940.508001');
    expect(calls.length).toBe(2);
    expect(calls[1].json).toEqual({
      channel: 'C123ABC456',
      text: payload.data.body,
      thread_ts: '1676056940.508000',
    });
  });

  it('throws on missing required field comment.body', async () => {
    const payload: LinearWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, body: '' },
    };
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing comment.body');
  });

  it('throws on Linear GraphQL non-2xx response', async () => {
    const payload: LinearWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, reactionEmoji: 'thumbsup', identifier: 'C999ZZZ' },
    };
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401));
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Linear GraphQL mutation failed: 401 Unauthorized (POST https://api.linear.app/graphql)'
    );
  });

  it('throws on Slack non-2xx response', async () => {
    const payload: LinearWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, identifier: 'C999ZZZ' },
    };
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'channel_not_found' }, 404));
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Slack postMessage failed: 404 Not Found (POST https://slack.com/api/chat.postMessage)'
    );
  });

  it('derives thread_ts from comment.createdAt when defaultSlackThreadTs not provided', async () => {
    const payload: LinearWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, identifier: 'C999ZZZ' },
    };
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://slack.com/api/chat.postMessage') {
        return jsonResponse({ ok: true, channel: 'C999ZZZ', ts: '1676056940.508001' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config = { ...baseConfig, defaultSlackThreadTs: undefined };
    await handle(payload, { ...config, fetch });
    expect(calls[0].json).toEqual({
      channel: 'C999ZZZ',
      text: payload.data.body,
      thread_ts: '1579783998.084000', // 2020-01-23T12:53:18.084Z in seconds with 6 decimals
    });
  });

  it('throws when both identifier and defaultSlackChannel are missing', async () => {
    const payload: LinearWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data },
    };
    const config = { ...baseConfig, defaultSlackChannel: undefined };
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    await expect(handle(payload, { ...config, fetch })).rejects.toThrow(
      'Missing Slack channel: comment.identifier and config.defaultSlackChannel are both absent'
    );
  });
});

# Linear Comment Reaction & Slack Mirror Connector

This connector handles the `comment.created` webhook from Linear. When a new comment is created, it:
1. Adds a reaction (emoji) to the comment via Linear's GraphQL API (if the payload includes a reaction emoji).
2. Mirrors the comment body into a Slack thread using `chat.postMessage`.

## Configuration

The connector requires the following environment variables (provided via `ConnectorConfig`):

| Config Property | Environment Variable | Description |
|-----------------|----------------------|-------------|
| `linearApiKey` | `LINEAR_API_KEY` | Bearer token for Linear GraphQL API. |
| `slackBotToken` | `SLACK_BOT_TOKEN` | Bearer token for Slack API (requires `chat:write` scope). |
| `linearWebhookSecret` | `LINEAR_WEBHOOK_SECRET` | Secret used to verify Linear webhook signatures (currently assumed verified by platform). |
| `defaultSlackChannel` | `DEFAULT_SLACK_CHANNEL` | (Optional) Fallback Slack channel ID if the comment payload lacks an `identifier`. |
| `defaultSlackThreadTs` | `DEFAULT_SLACK_THREAD_TS` | (Optional) Fallback thread timestamp if not derived from comment creation time. |
| `skipTimestampCheck` | `SKIP_TIMESTAMP_CHECK` | (Optional) Set to `true` to disable the 60-second replay protection check (useful for testing). |

## Usage Example

```typescript
import { handle, ConnectorConfig, LinearWebhookPayload } from './connector';

const config: ConnectorConfig = {
  linearApiKey: process.env.LINEAR_API_KEY!,
  slackBotToken: process.env.SLACK_BOT_TOKEN!,
  linearWebhookSecret: process.env.LINEAR_WEBHOOK_SECRET!,
  defaultSlackChannel: process.env.DEFAULT_SLACK_CHANNEL,
  defaultSlackThreadTs: process.env.DEFAULT_SLACK_THREAD_TS,
  skipTimestampCheck: process.env.NODE_ENV === 'test',
};

// In your webhook handler (e.g., Express, Fastify, etc.):
app.post('/linear-webhook', async (req, res) => {
  try {
    const payload = req.body as LinearWebhookPayload;
    const result = await handle(payload, config);
    res.json({ success: true, ...result });
  } catch (err) {
    console.error(err);
    res.status(400).json({ error: err.message });
  }
});
```

## Assumptions

- The Linear webhook payload includes `comment.id`, `comment.body`, `comment.createdAt`, and optionally `comment.reactionEmoji` and `comment.identifier`.
- The Linear GraphQL API uses the `reactionAdd` mutation with `reactableId` (comment ID) and `react` (emoji string).
- The Slack bot token has the `chat:write` scope.
- The Slack thread timestamp (`thread_ts`) is either provided by the webhook, derived from the Linear comment's `createdAt`, or supplied via `defaultSlackThreadTs`.
- The platform (or upstream middleware) verifies the `Linear-Signature` header using `LINEAR_WEBHOOK_SECRET`. The connector only checks the `webhookTimestamp` field for replay protection (within 60 seconds).
- If `comment.reactionEmoji` is absent, the reaction step is skipped.
- If `comment.identifier` is absent, `defaultSlackChannel` must be configured.
- All external calls use the injected `fetch` (or global `fetch`) for testability.

