export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://api.linear.app/graphql",
    "response": {
      "data": {
        "reactionAdd": {
          "success": true,
          "reaction": {
            "id": "reaction-id-example"
          }
        }
      }
    }
  },
  {
    "method": "POST",
    "url": "https://slack.com/api/chat.postMessage",
    "response": {
      "ok": true,
      "channel": "C123ABC456",
      "ts": "1355517523.000006",
      "message": {
        "text": "Indeed, I think this is definitely an improvement over the previous version.",
        "ts": "1355517523.000006",
        "type": "message",
        "subtype": "bot_message"
      }
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  linearApiKey: string;
  slackBotToken: string;
  linearWebhookSecret: string;
  defaultSlackChannel?: string;
  defaultSlackThreadTs?: string;
  skipTimestampCheck?: boolean;
  fetch?: typeof fetch;
}

export interface LinearWebhookPayload {
  action: string;
  actor: {
    id: string;
    type: string;
    name: string;
    email: string;
    url: string;
  };
  data: {
    id: string;
    createdAt: string;
    updatedAt: string;
    archivedAt: string | null;
    body: string;
    edited: boolean;
    issueId: string;
    userId: string;
    reactionType?: string;
    reactionEmoji?: string;
    identifier?: string;
  };
  type: string;
  url: string;
  createdAt: string;
  organizationId: string;
  webhookTimestamp: number;
  webhookId: string;
}

export interface HandleResult {
  reactionId?: string;
  slackMessageTs?: string;
}

async function verifySignature(_payload: LinearWebhookPayload, _config: ConnectorConfig): Promise<void> {
  // Signature verification would require the raw request body and the Linear-Signature header.
  // Since the connector only receives the parsed payload, we assume the platform has verified the signature.
  // If config provided rawBody and signatureHeader, we could implement HMAC verification here.
}

async function checkReplayProtection(payload: LinearWebhookPayload, config: ConnectorConfig): Promise<void> {
  if (config.skipTimestampCheck) return;
  const now = Date.now();
  const webhookTime = payload.webhookTimestamp;
  const diff = Math.abs(now - webhookTime);
  const sixtySeconds = 60 * 1000;
  if (diff > sixtySeconds) {
    throw new Error(`Webhook timestamp too old: ${diff}ms difference (max 60000ms)`);
  }
}

async function addLinearReaction(commentId: string, emoji: string, config: ConnectorConfig): Promise<string> {
  const query = `mutation AddReaction($input: ReactionAddInput!) { reactionAdd(input: $input) { success reaction { id } } }`;
  const variables = {
    input: {
      reactableId: commentId,
      react: emoji,
    },
  };
  const fetchFn = config.fetch ?? fetch;
  const response = await fetchFn('https://api.linear.app/graphql', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.linearApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ query, variables }),
  });
  if (!response.ok) {
    throw new Error(`Linear GraphQL mutation failed: ${response.status} ${response.statusText} (POST https://api.linear.app/graphql)`);
  }
  const data = await response.json();
  if (!data.data?.reactionAdd?.success) {
    throw new Error('Linear reaction add failed: success false');
  }
  return data.data.reactionAdd.reaction.id;
}

async function postSlackMessage(channel: string, text: string, threadTs: string, config: ConnectorConfig): Promise<string> {
  const fetchFn = config.fetch ?? fetch;
  const response = await fetchFn('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ channel, text, thread_ts: threadTs }),
  });
  if (!response.ok) {
    throw new Error(`Slack postMessage failed: ${response.status} ${response.statusText} (POST https://slack.com/api/chat.postMessage)`);
  }
  const data = await response.json();
  if (!data.ok) {
    throw new Error('Slack postMessage failed: ok false');
  }
  return data.ts;
}

export async function handle(payload: LinearWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!payload || payload.action !== 'create' || payload.type !== 'Comment') {
    throw new Error('Invalid payload: not a comment creation event');
  }
  const comment = payload.data;
  if (!comment.id) throw new Error('Missing comment.id');
  if (!comment.body) throw new Error('Missing comment.body');
  if (!comment.createdAt) throw new Error('Missing comment.createdAt');

  await verifySignature(payload, config);
  await checkReplayProtection(payload, config);

  const result: HandleResult = {};

  if (comment.reactionEmoji) {
    const reactionId = await addLinearReaction(comment.id, comment.reactionEmoji, config);
    result.reactionId = reactionId;
  }

  const channel = comment.identifier || config.defaultSlackChannel;
  if (!channel) {
    throw new Error('Missing Slack channel: comment.identifier and config.defaultSlackChannel are both absent');
  }

  const threadTs = config.defaultSlackThreadTs || (() => {
    const date = new Date(comment.createdAt);
    if (isNaN(date.getTime())) throw new Error('Invalid comment.createdAt for thread_ts derivation');
    return (date.getTime() / 1000).toFixed(6);
  })();

  const slackTs = await postSlackMessage(channel, comment.body, threadTs, config);
  result.slackMessageTs = slackTs;

  return result;
}

